// Valida el evento contra el contrato y prepara el mensaje. No se aceptan campos
// sensibles: si llegan, se descartan y no se reenvían.
const allowed = {
  APPOINTMENT_APPROVED: ['Cita aprobada', 'Tu solicitud de cita fue aprobada.'],
  APPOINTMENT_REJECTED: ['Solicitud de cita rechazada', 'Tu solicitud de cita fue rechazada.'],
  APPOINTMENT_CANCELLED: ['Cita cancelada', 'Tu cita fue cancelada.'],
  RESCHEDULE_APPROVED: ['Reprogramación aprobada', 'Tu cita fue reprogramada.'],
  RESCHEDULE_REJECTED: ['Reprogramación rechazada', 'Tu solicitud de reprogramación fue rechazada; tu cita original se mantiene.']
};
const e = items[0].json.body || {};
const errors = [];
for (const f of ['eventId', 'correlationId', 'type', 'occurredAt', 'appointmentId', 'status', 'startAt']) {
  if (e[f] === undefined || e[f] === null || e[f] === '') errors.push(f);
}
if (!e.recipient || !e.recipient.email) errors.push('recipient.email');
if (e.type && !allowed[e.type]) errors.push('type');
if (errors.length) {
  return [{ json: { valid: false, errors, correlationId: e.correlationId || null } }];
}
const [subject, lead] = allowed[e.type];
const when = String(e.startAt).replace('T', ' a las ');
const reason = e.reason ? ' Motivo: ' + e.reason + '.' : '';
return [{ json: {
  valid: true,
  eventId: e.eventId,
  correlationId: e.correlationId,
  type: e.type,
  appointmentId: e.appointmentId,
  email: e.recipient.email,
  subject: subject + ' - FCV Demo (sintético)',
  message: 'Hola ' + (e.recipient.firstName || '') + '. ' + lead + ' Cita #' + e.appointmentId + ' (' + when + ').' + reason + ' Mensaje del entorno sintético de laboratorio.'
} }];
